class MeineQueue {
   private Knoten anfang; 
   private Knoten ende; 

   boolean add(Knoten knoten) {
      if(ende != null) {
         ende.setNachfolger(knoten);
      } else {
         anfang = knoten; 
      }
      ende = knoten; 
      return true; 
   }

   Knoten poll() {
      if(anfang != null) {
         // speichere anfang zwischen
         Knoten temp = anfang; 
         // anfang bereits letzer Knoten
         if(anfang.getNachfolger() == null) {
            ende = null; 
         }
         // bei letzem Knoten dann null, passt auch
         anfang = anfang.getNachfolger();
         return temp; 
      } else {
         return null; 
      }


   }

   Knoten getAnfang() {
      return anfang;
   }

   void setAnfang(Knoten anfang) {
      this.anfang = anfang;
   }

   Knoten getEnde() {
      return ende;
   }

   void setEnde(Knoten ende) {
      this.ende = ende;
   }


}

